// Verify hand-assembled demo ROM: key-controlled sprite mover
const rom = [
0x60,0x00, // 200: V0=0 (x)
0x61,0x00, // 202: V1=0 (y)
0xA2,0x38, // 204: I=0x238 (sprite)
0xD0,0x15, // 206: LOOP: draw 5-byte sprite at (V0,V1)
0x62,0x02, // 208: V2=2
0xF2,0x15, // 20A: delay=V2
0xF2,0x07, // 20C: WAIT: V2=delay
