0xD0,0x15, // 212: erase sprite (XOR again, same pos)
0x62,0x44, // 214: V2=4 (left)
0xE2,0xA1, // 216: skip if key 4 NOT pressed
0x70,0xFF, // 218: V0 += -1
0x62,0x46, // 21A: V2=6 (right)
0xE2,0xA1, // 21C: skip if not pressed
0x70,0x01, // 21E: V0 += 1
0x62,0x42, // 220: V2=2 (up)
0xE2,0xA1, // 222: skip if not pressed
0x71,0xFF, // 224: V1 += -1
0x62,0x48, // 226: V2=8 (down)
0xE2,0xA1, // 228: skip if not pressed
0x71,0x01, // 22A: V1 += 1
0x62,0x3F, // 22C: V2=0x3F
0x80,0x22, // 22E: V0 &= V2 (wrap x 0..63)
0x62,0x1F, // 230: V2=0x1F
0x80,0x12, // 232: V1 &= V2 (wrap y 0..31)
0x12,0x06, // 234: jump LOOP
0x00,0x00, // 236: padding
0x20,0x70,0xF8,0x70,0x20 // 238: sprite (diamond)
];
// Mini interpreter to smoke-test: run with key 6 held, ensure x increases and no crash
const mem = new Uint8Array(4096); rom.forEach((b,i)=>mem[0x200+i]=b);
const V = new Uint8Array(16); let I=0, pc=0x200, delay=0;
const keys = new Array(16).fill(false); keys[6]=true; // hold "right"
let steps=0, draws=0;
while(steps++ < 200000){
  const op = (mem[pc]<<8)|mem[pc+1]; const nnn=op&0xFFF, nn=op&0xFF, n=op&0xF, x=(op>>8)&0xF, y=(op>>4)&0xF;
  const oldpc=pc; pc+=2;
  switch(op&0xF000){
    case 0x0000: if(nn===0xEE){} break;
    case 0x1000: pc=nnn; break;
    case 0x3000: if(V[x]===nn) pc+=2; break;
    case 0x6000: V[x]=nn; break;
    case 0x7000: V[x]=(V[x]+nn)&0xFF; break;
    case 0x8000: if(n===2) V[x]&=V[y]; break;
    case 0xA000: I=nnn; break;
    case 0xD000: draws++; break;
    case 0xE000: if(nn===0xA1 && !keys[V[x]]) pc+=2; break;
    case 0xF000:
      if(nn===0x15) delay=V[x];
      else if(nn===0x07) V[x]=delay;
      break;
    default: throw new Error('bad op '+op.toString(16)+' @'+oldpc.toString(16));
  }
  if(steps%60===0 && delay>0) delay--;
  if(steps===50000) console.log('after 50k steps: x='+V[0]+' y='+V[1]+' draws='+draws+' pc=0x'+pc.toString(16));
}
console.log('final: x='+V[0]+' y='+V[1]+' draws='+draws+' (x should have increased from 0, sprite drawn/erased alternately)');
console.log('ROM length:', rom.length, 'bytes; sprite at 0x238 =', mem.slice(0x238,0x23D).join(','));
"}

{"language":"javascript","code":"// Verify hand-assembled demo ROM v2: draw sprite, move diagonally while key 5 held
const rom = [
  0x60,0x00, // 200: V0=0 (x)
  0x61,0x08, // 202: V1=8 (y)
  0x62,0x05, // 204: V2=5 (key to watch)
  0xA2,0x38, // 206: I=0x238 (sprite)
  0xD0,0x15, // 208: DRAW sprite at (V0,V1), 5 rows
  0xE2,0xA1, // 20A: skip next if key V2 NOT pressed
  0x12,0x10, // 20C: pressed -> jump MOVE
  0x12,0x14, // 20E: not pressed -> jump ERASE
  0x70,0x01, // 210: MOVE: V0+=1
  0x71,0x01, // 212: V1+=1
  0xD0,0x15, // 214: ERASE (XOR off)
  0x12,0x08, // 216: jump DRAW (0x208)
];
while (rom.length < 0x38) rom.push(0x00); // pad to sprite offset
rom.push(0x20,0x70,0xF8,0x70,0x20); // sprite: arrow/diamond at 0x238

const mem = new Uint8Array(4096); rom.forEach((b,i)=>mem[0x200+i]=b);
const V = new Uint8Array(16); const gfx = new Uint8Array(64*32);
let I=0, pc=0x200, draws=0;
const keyState = new Array(16).fill(false);
function step(){
  const op = mem[pc]<<8 | mem[pc+1]; pc += 2;
  const x=(op>>8)&0xF, y=(op>>4)&0xF, nnn=op&0xFFF, kk=op&0xFF, n=op&0xF;
  switch(op&0xF000){
    case 0x0000: if(op===0x00E0) gfx.fill(0); break;
    case 0x1000: pc=nnn; break;
    case 0x6000: V[x]=kk; break;
    case 0x7000: V[x]=(V[x]+kk)&0xFF; break;
    case 0xA000: I=nnn; break;
    case 0xD000: { V[0xF]=0;
      for(let r=0;r<n;r++){ const b=mem[I+r];
        for(let c=0;c<8;c++){ if(b&(0x80>>c)){
          const px=(V[x]+c)%64, py=(V[y]+r)%32, i=py*64+px;
          if(gfx[i])V[0xF]=1; gfx[i]^=1; } } }
      draws++; break; }
    case 0xE000:
      if(kk===0xA1){ if(!keyState[V[x]]) pc+=2; }
      else if(kk===0x9E){ if(keyState[V[x]]) pc+=2; }
      break;
  }
}
// Phase 1: no key pressed -> sprite drawn once, stays at (0,8)
for(let i=0;i<1000;i++) step();
console.log('no-key: x='+V[0]+' y='+V[1]+' draws='+draws+' (expect x=0 y=8 draws=1)');
// Phase 2: hold key 5 -> sprite moves diagonally, wraps
keyState[5]=true;
for(let i=0;i<200000;i++) step();
console.log('key5 held: x='+V[0]+' y='+V[1]+' draws='+draws+' (expect x,y advanced, many draws)');
console.log('ROM length: '+rom.length+' bytes; sprite at 0x238 = '+rom.slice(0x38).join(','));
"}

